<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class InvoiceItem extends Model { use HasUuids; protected $fillable=['invoice_id','activity_session_id','project_id','activity_type_id','description','started_at','billable_seconds','base_rate_minor','customer_multiplier','project_multiplier','effective_rate_minor','amount_minor','currency','resolution_source','pricing_override_id']; protected $casts=['started_at'=>'datetime','billable_seconds'=>'integer','base_rate_minor'=>'integer','effective_rate_minor'=>'integer','amount_minor'=>'integer','customer_multiplier'=>'decimal:4','project_multiplier'=>'decimal:4']; public function invoice(){return $this->belongsTo(Invoice::class);} public function activity(){return $this->belongsTo(ActivitySession::class,'activity_session_id');} public function project(){return $this->belongsTo(Project::class);} public function activityType(){return $this->belongsTo(ActivityType::class);} }
